@use '@smart/web-components/dist/scss/variables' as *;

.subscriptions-card {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: space-between;
  min-height: 448px;
  max-height: 517px;
  padding: var(--spacing-400);
  background-color: var(--bg-level-1);
  box-shadow:
    0 8px 16px 0 rgba(0, 0, 0, 0.08),
    0 0 16px 0 rgba(0, 0, 0, 0.08);

  @include breakpoint(l) {
    width: calc((100% - 2 * var(--spacing-400)) / 3);
  }

  &__product-name {
    font-weight: 700;
    margin-bottom: var(--spacing-100);
  }

  &__product-type {
    letter-spacing: -0.8px;
    overflow-wrap: anywhere;
    word-break: keep-all;
    hyphens: auto;
    min-width: 0;
    margin-bottom: var(--spacing-400);
  }

  &__bottom-section {
    width: 100%;
  }

  &__status-indicator {
    display: flex;
    align-items: center;
    gap: var(--spacing-100);
    margin-top: var(--spacing-100);
  }

  &__status-dot {
    width: 20px;
    height: 20px;
    border-radius: 50%;

    &[data-status='active'] {
      background-color: var(--sig-success);
    }

    &[data-status='processing'] {
      background-color: var(--sig-warning);
    }

    &[data-status='inactive'] {
      background-color: var(--sig-error);
    }
  }

  &__status-text {
    font-weight: 700;
  }

  &__expire-date {
    color: var(--sig-error);
  }

  &__renew-button,
  &__details-button {
    width: 100%;
  }

  &__renew-button {
    margin-bottom: 10px;
  }

  hr {
    width: 100%;
    margin: 0;
    border: 0;
    border-top: 1px solid var(--div-default);
  }
}

