import {Flex, Text} from '@smart/react-components';
import {PRODUCT_TYPE, type PaymentType} from '@smart/types';
import React, {useEffect} from 'react';
import {SubscriptionDetailsI18nKeys} from '../../../../generated/i18n/SubscriptionDetails';
import {useAppModelLoggedInContext} from '../../hooks/use-app-model';
import {useFeatureAppEnv} from '../../hooks/use-feature-app-env';
import {useProductDetailsNavigationTarget} from '../../hooks/use-product-details-navigation';
import {useServiceDetails} from '../../hooks/use-service-details';
import {useTranslations} from '../../hooks/use-translations';
import {BackButton} from '../BackButton/BackButton';
import LoaderForComponents from '../LoaderForComponents/LoaderForComponents';
import {routes} from '../MyAccount/MyAccountLayout';
import styles from './SubscriptionDetails.module.scss';
import {SubscriptionGeneralInfo} from './SubscriptionGeneralInfo/SubscriptionGeneralInfo';
import {SubscriptionProductDisplay} from './SubscriptionProductDisplay/SubscriptionProductDisplay';

const baseClass = `subscription-details`;

export const SubscriptionDetails: React.FC = () => {
  const {
    featureServices: {'s2:history': historyService},
  } = useFeatureAppEnv();
  const {history} = historyService;
  const translate = useTranslations();

  const {fetchData, data: serviceDetails} = useServiceDetails();

  const {
    content: {myOrders},
  } = useAppModelLoggedInContext();

  const productCode =
    serviceDetails?.productType === PRODUCT_TYPE.CONNECTED_SERVICE &&
    serviceDetails?.extendServiceProductCode
      ? serviceDetails.extendServiceProductCode
      : serviceDetails?.productCode;

  const productDetails = useProductDetailsNavigationTarget(
    myOrders.productDetailsPageReference,
    productCode,
    `accessoryCode`,
  );

  useEffect(() => {
    const searchParams = new URLSearchParams(history.location.search);
    const serviceId = searchParams.get(`id`);

    if (serviceId) {
      fetchData(serviceId);
    }
  }, []);

  return serviceDetails ? (
    <div className={styles[baseClass]}>
      <BackButton
        label={translate(
          SubscriptionDetailsI18nKeys[
            `subscriptionDetails.cta.backToOrderOverview`
          ],
        )}
        route={routes.subscriptions}
      />

      <Text
        as="h1"
        variant="hl-300"
        className={styles[`${baseClass}__headline`]}
      >
        {translate(SubscriptionDetailsI18nKeys[`subscriptionDetails.headline`])}
      </Text>

      <Text variant="hl-100" as="h4" margin={{bottom: 500}}>
        {translate(
          SubscriptionDetailsI18nKeys[
            `subscriptionDetails.generalInfo.headline`
          ],
        )}
      </Text>

      <Flex direction={`column`} gap={500}>
        <SubscriptionGeneralInfo
          subscriptionDetails={serviceDetails}
          productDetails={productDetails}
        />
        <SubscriptionProductDisplay
          productCode={serviceDetails.productCode}
          productName={serviceDetails.productName}
          paymentTypeCode={serviceDetails.paymentTypeCode as PaymentType}
          totalPriceFormatted={
            serviceDetails.orderEntryInfo?.totalPrice?.formattedValue ?? ``
          }
        />
      </Flex>
    </div>
  ) : (
    <LoaderForComponents />
  );
};

